    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.baseTypeEClass, source, new String[]{"documentation", "This abstract meta-class represents the ability to specify a platform dependant base type."});
        this.addAnnotation((ENamedElement)this.getBaseType_BaseTypeDefinition(), source, new String[]{"documentation", "This is the actual definition of the base type."});
        this.addAnnotation((ENamedElement)this.baseTypeDefinitionEClass, source, new String[]{"documentation", "This meta-class represents the ability to define a basetype."});
        this.addAnnotation((ENamedElement)this.baseTypeAbsSizeEClass, source, new String[]{"documentation", "This is the absolute size of the basetype. In this case the BaseType is of fixed length."});
        this.addAnnotation((ENamedElement)this.baseTypeAbsSizeEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)baseTypeSize.clone();"});
        this.addAnnotation((ENamedElement)this.baseTypeAbsSizeEClass.getEOperations().get(1), source, new String[]{"body", "baseTypeSize.setRadix(newBaseTypeSize.getRadix());\nbaseTypeSize.setNoOfDigits(newBaseTypeSize.getNoOfDigits());\nsetBaseTypeSize(newBaseTypeSize.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getBaseTypeAbsSize_BaseTypeSize(), source, new String[]{"documentation", "Describes the length of the data type specified in the container in bits."});
        this.addAnnotation((ENamedElement)this.baseTypeSizeDefinitionEClass, source, new String[]{"documentation", "This abstract class represents the possible methods of defining the size of a BaseType."});
        this.addAnnotation((ENamedElement)this.baseTypeDirectDefinitionEClass, source, new String[]{"documentation", "This BaseType is defined directly (as opposite to a derived BaseType)"});
        this.addAnnotation((ENamedElement)this.baseTypeDirectDefinitionEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)memAlignment.clone();"});
        this.addAnnotation((ENamedElement)this.baseTypeDirectDefinitionEClass.getEOperations().get(1), source, new String[]{"body", "memAlignment.setRadix(newMemAlignment.getRadix());\nmemAlignment.setNoOfDigits(newMemAlignment.getNoOfDigits());\nsetMemAlignment(newMemAlignment.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getBaseTypeDirectDefinition_BaseTypeSizeDefintionType(), source, new String[]{"documentation", "This aggregation is necessary to specify the exact sequence of properties in the xml-file. It represents the size of the BaseType."});
        this.addAnnotation((ENamedElement)this.getBaseTypeDirectDefinition_BaseTypeEncoding(), source, new String[]{"documentation", "This specifies, how an object of the current BaseType is encoded e.g.. in an ECU in a message sequence."});
        this.addAnnotation((ENamedElement)this.getBaseTypeDirectDefinition_MemAlignment(), source, new String[]{"documentation", "This attribute describes the alignment of the memory object in bits. E.g. \"1\" specifies, that the object in question is aligned to a byte while \"32\" specifies that it is aligned four byte."});
        this.addAnnotation((ENamedElement)this.getBaseTypeDirectDefinition_ByteOrder(), source, new String[]{"documentation", "This attribute specifies the byte order of the base type."});
        this.addAnnotation((ENamedElement)this.getBaseTypeDirectDefinition_NativeDeclaration(), source, new String[]{"documentation", "This attribute describes the declaration of such a base type in the native programming language, primarily in the Programming language C. This can then be used by a code generator to include the necessary declarations into a header file. For example\r\n\r\nBaseType with\r\n   shortName: \"MyUnsignedInt\"\r\n   nativeDeclaration: \"unsigned short\"\r\n\r\nResults in\r\n\r\n  typedef unsigned short MyUnsignedInt;\r\n\r\nIf the attribute is not defined the referring ImplementationDataTypes will not be generated as a typedef by RTE.\r\n\r\nIf a nativeDeclaration type is given it shall fulfill the characteristic given by basetypeEncoding and baseTypeSize. This is required to ensure the consistent handling and interpretation by software components, RTE, COM and MCM systems."});
        this.addAnnotation((ENamedElement)this.baseTypeEncodingStringEDataType, source, new String[]{"documentation", "This is the string denotion of a BaseType encoding. It may be refined by specific use-cases."});
        this.addAnnotation((ENamedElement)this.baseTypeMaxSizeEClass, source, new String[]{"documentation", "This is the maximum size of a BaseType in case of a dynamic BaseType."});
        this.addAnnotation((ENamedElement)this.baseTypeMaxSizeEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)maxBaseTypeSize.clone();"});
        this.addAnnotation((ENamedElement)this.baseTypeMaxSizeEClass.getEOperations().get(1), source, new String[]{"body", "maxBaseTypeSize.setRadix(newMaxBaseTypeSize.getRadix());\nmaxBaseTypeSize.setNoOfDigits(newMaxBaseTypeSize.getNoOfDigits());\nsetMaxBaseTypeSize(newMaxBaseTypeSize.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getBaseTypeMaxSize_MaxBaseTypeSize(), source, new String[]{"documentation", "Describes the maximum length of the BaseType  in bits"});
        this.addAnnotation((ENamedElement)this.swBaseTypeEClass, source, new String[]{"documentation", "This meta-class represents a base type used within ECU software."});
    }

